def chain_follower(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []

    current = chain_dict['xds']
    chain_dict['xds'] = []

    while current:
        chain_dict[current].append(current)
        current = chain_dict[current][0]

    chain_dict['xds'].append(current)

    return ', '.join(chain_dict['xds'])
